SELECT
FROM sys_user WHERE deleted = 0
AND username LIKE CONCAT('%', #{user.username}, '%')
AND real_name LIKE CONCAT('%', #{user.realName}, '%')
AND status = #{user.status}
ORDER BY create_time DESC LIMIT #{offset}, #{limit}

mapper.insert:
INSERT INTO sys_user (
    username, password, real_name, email, phone, status,
    create_time, update_time, create_by, update_by, deleted, version, user_type, permission_settings
) VALUES (
    #{username}, #{password}, #{realName}, #{email}, #{phone}, #{status},
    #{createTime}, #{updateTime}, #{createBy}, #{updateBy}, #{deleted}, #{version}, #{userType}, #{permissionSettings}
)

mapper.update:
UPDATE sys_user
username = #{username}, password = #{password}, real_name = #{realName}, email = #{email}, phone = #{phone}, status = #{status}, update_time = #{updateTime}, update_by = #{updateBy}, version = version + 1, user_type = #{userType}, permission_settings = #{permissionSettings}
WHERE id = #{id} AND deleted = 0
